struct Node;

/// Upper bound on the question length, from the node's `ensures` clause.
const MAX_QUESTION_CHARS: usize = 512;

/// Sentinel used when the knowledge base has nothing for the question, so
/// that `ensures present(knowledge)` holds without inventing content.
const NO_KNOWLEDGE: &str = "no knowledge base entry matched this question";

impl Guest for Node {
    fn run(query: ModeratedQuery) -> ConversationContext {
        let intent = query.query.intent;

        // `requires` guarantees the bound already; truncating by characters
        // keeps the `ensures` clause true even if that precondition is violated.
        let mut question = query.query.question;
        if question.chars().count() > MAX_QUESTION_CHARS {
            question = question.chars().take(MAX_QUESTION_CHARS).collect();
        }

        let mut knowledge = crate::aap::caps::kb_read::lookup(&question);
        if knowledge.is_empty() {
            knowledge.push(NO_KNOWLEDGE.to_string());
        }

        ConversationContext {
            intent,
            question,
            knowledge,
        }
    }
}

export!(Node);
